16	import { RvfEmbeddingService } from '../v3/@claude-flow/embeddings/src/rvf-embedding-service.js';
17	
18	// ---------------------------------------------------------------------------
19	// Helpers
20	// ---------------------------------------------------------------------------
21	
22	let tmpDir: string;
23	
24	function makeTmpDir(): string {
25	  return mkdtempSync(join(tmpdir(), 'rvf-test-'));
26	}
27	
28	function makeEmbedding(dims: number, fill = 0.5): Float32Array {
29	  const arr = new Float32Array(dims);
30	  arr.fill(fill);
31	  return arr;
32	}
33	
34	function l2Norm(v: Float32Array): number {
35	  let sum = 0;
36	  for (let i = 0; i < v.length; i++) sum += v[i] * v[i];
37	  return Math.sqrt(sum);
38	}
