355	        message: /not been initialized/,
356	      });
357	      await assert.rejects(() => uninit.saveEwcState(makeEwc()), {
358	        message: /not been initialized/,
359	      });
360	      await assert.rejects(() => uninit.loadEwcState(), { message: /not been initialized/ });
361	      await assert.rejects(() => uninit.appendTrajectory(makeTrajectory()), {
362	        message: /not been initialized/,
363	      });
364	      await assert.rejects(() => uninit.getTrajectories(), { message: /not been initialized/ });
365	      await assert.rejects(() => uninit.getTrajectoryCount(), {
366	        message: /not been initialized/,
367	      });
368	      await assert.rejects(() => uninit.getStats(), { message: /not been initialized/ });
369	    });
370	
371	    it('corrupt file is handled gracefully (bad header)', async () => {
372	      fs.writeFileSync(storePath, 'NOT_RVLS\n{"type":"pattern","data":{}}\n');
373	      await store.initialize(); // should not throw
