381	      assert.equal(await store.getPatternCount(), 1);
382	    });
383	  });
384	
385	  // ===== 9. Edge Cases =====
386	
387	  describe('edge cases', () => {
388	    it('empty store returns empty arrays and zero counts', async () => {
389	      await store.initialize();
390	      assert.deepEqual(await store.loadPatterns(), []);
391	      assert.deepEqual(await store.loadLoraAdapters(), []);
392	      assert.equal(await store.loadEwcState(), null);
