406	        await store.appendTrajectory(makeTrajectory({ id: `t${i}` }));
407	      }
408	      await store.persist();
409	      await store.close();
410	
411	      const store2 = new RvfLearningStore({ storePath, autoPersistInterval: 0 });
412	      await store2.initialize();
413	      assert.equal(await store2.getPatternCount(), 200);
