408	    const dims = 2;
409	    const embedding = new Float32Array([3.14, 2.71]);
410	    // v1 entry: hash(4) + dims(4) + data(dims*4) + accessedAt(8) + accessCount(8)
411	    const entrySize = 4 + 4 + dims * 4 + 8 + 8;
412	    const buf = Buffer.alloc(MAGIC.length + entrySize);
413	    buf.set(MAGIC, 0);
414	    let off = MAGIC.length;
415	    buf.writeUInt32LE(12345, off); off += 4; // hash
416	    buf.writeUInt32LE(dims, off); off += 4;
417	    for (let i = 0; i < dims; i++) { buf.writeFloatLE(embedding[i], off); off += 4; }
418	    buf.writeDoubleLE(Date.now(), off); off += 8; // accessedAt
419	    buf.writeDoubleLE(5, off); // accessCount
