1	import { existsSync } from 'node:fs';
2	import { readFile, writeFile, mkdir, rename } from 'node:fs/promises';
3	import { dirname, resolve } from 'node:path';
4	import type {
5	  IMemoryBackend,
6	  MemoryEntry,
7	  MemoryEntryUpdate,
8	  MemoryQuery,
9	  SearchOptions,
10	  SearchResult,
11	  BackendStats,
12	  HealthCheckResult,
13	  MemoryType,
14	} from './types.js';
15	
16	// ----------------------------------------------------------------------------
17	// HnswLite — small brute-force-degrading HNSW used ONLY by RvfBackend.
18	// Inlined here by ADR-125 Phase 3 so the canonical `src/hnsw-index.ts` can be
19	// the single HNSW implementation in the public surface. Not exported.
20	// ----------------------------------------------------------------------------
21	
22	interface HnswSearchResult {
23	  id: string;
24	  score: number;
25	}
26	
27	class HnswLite {
28	  private vectors = new Map<string, Float32Array>();
29	  private neighbors = new Map<string, Set<string>>();
30	  private readonly dimensions: number;
31	  private readonly maxNeighbors: number;
32	  private readonly efConstruction: number;
33	  private readonly metric: string;
34	
35	  constructor(dimensions: number, m: number, efConstruction: number, metric: string) {
36	    this.dimensions = dimensions;
37	    this.maxNeighbors = m;
38	    this.efConstruction = efConstruction;
39	    this.metric = metric;
40	  }
41	
42	  get size(): number { return this.vectors.size; }
43	
44	  add(id: string, vector: Float32Array): void {
45	    this.vectors.set(id, vector);
46	    if (this.vectors.size === 1) {
47	      this.neighbors.set(id, new Set());
48	      return;
49	    }
50	    const nearest = this.findNearest(vector, this.maxNeighbors);
51	    const neighborSet = new Set<string>();
52	    for (const n of nearest) {
53	      neighborSet.add(n.id);
54	      const nNeighbors = this.neighbors.get(n.id);
55	      if (nNeighbors) {
56	        nNeighbors.add(id);
57	        if (nNeighbors.size > this.maxNeighbors * 2) this.pruneNeighbors(n.id);
58	      }
59	    }
60	    this.neighbors.set(id, neighborSet);
61	  }
62	
63	  remove(id: string): void {
64	    this.vectors.delete(id);
65	    const my = this.neighbors.get(id);
66	    if (my) for (const nId of my) this.neighbors.get(nId)?.delete(id);
67	    this.neighbors.delete(id);
68	  }
69	
70	  search(query: Float32Array, k: number, threshold?: number): HnswSearchResult[] {
71	    if (this.vectors.size === 0) return [];
72	    if (this.vectors.size <= k * 2) return this.bruteForce(query, k, threshold);
73	
74	    const visited = new Set<string>();
75	    const candidates: HnswSearchResult[] = [];
76	
77	    let entryId: string | undefined;
78	    let bestScore = -1;
79	    for (const [id] of this.vectors) {
80	      const score = this.similarity(query, this.vectors.get(id)!);
81	      if (score > bestScore) { bestScore = score; entryId = id; }
82	      if (visited.size >= Math.min(this.efConstruction, this.vectors.size)) break;
83	      visited.add(id);
84	      candidates.push({ id, score });
85	    }
86	
87	    if (entryId) {
88	      const queue = [entryId];
89	      let idx = 0;
90	      while (idx < queue.length && visited.size < this.efConstruction * 2) {
91	        const currentId = queue[idx++];
92	        const currentNeighbors = this.neighbors.get(currentId);
93	        if (!currentNeighbors) continue;
94	        for (const nId of currentNeighbors) {
95	          if (visited.has(nId)) continue;
96	          visited.add(nId);
97	          const vec = this.vectors.get(nId);
98	          if (!vec) continue;
99	          const score = this.similarity(query, vec);
100	          candidates.push({ id: nId, score });
101	          queue.push(nId);
102	        }
103	      }
104	    }
105	
106	    candidates.sort((a, b) => b.score - a.score);
107	    let filtered = candidates;
108	    if (threshold !== undefined) filtered = filtered.filter(c => c.score >= threshold);
109	    return filtered.slice(0, k);
110	  }
111	
112	  private bruteForce(query: Float32Array, k: number, threshold?: number): HnswSearchResult[] {
113	    const results: HnswSearchResult[] = [];
114	    for (const [id, vec] of this.vectors) {
115	      const score = this.similarity(query, vec);
116	      if (threshold !== undefined && score < threshold) continue;
117	      results.push({ id, score });
118	    }
119	    results.sort((a, b) => b.score - a.score);
120	    return results.slice(0, k);
121	  }
122	
123	  private findNearest(query: Float32Array, k: number): HnswSearchResult[] {
124	    return this.bruteForce(query, k);
125	  }
126	
127	  private pruneNeighbors(id: string): void {
128	    const my = this.neighbors.get(id);
129	    if (!my) return;
130	    const vec = this.vectors.get(id);
131	    if (!vec) return;
132	    const scored: HnswSearchResult[] = [];
133	    for (const nId of my) {
134	      const nVec = this.vectors.get(nId);
135	      if (!nVec) continue;
136	      scored.push({ id: nId, score: this.similarity(vec, nVec) });
137	    }
138	    scored.sort((a, b) => b.score - a.score);
139	    const keep = new Set(scored.slice(0, this.maxNeighbors).map(s => s.id));
140	    for (const nId of my) if (!keep.has(nId)) my.delete(nId);
141	  }
142	
143	  private similarity(a: Float32Array, b: Float32Array): number {
144	    if (this.metric === 'dot') return dotProduct(a, b);
145	    if (this.metric === 'euclidean') return 1 / (1 + euclideanDistance(a, b));
146	    return cosineSimilarity(a, b);
147	  }
148	}
149	
150	function cosineSimilarity(a: Float32Array, b: Float32Array): number {
151	  let dot = 0, normA = 0, normB = 0;
152	  for (let i = 0; i < a.length; i++) {
153	    dot += a[i] * b[i];
154	    normA += a[i] * a[i];
155	    normB += b[i] * b[i];
156	  }
157	  if (normA === 0 || normB === 0) return 0;
158	  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
159	}
160	
161	function dotProduct(a: Float32Array, b: Float32Array): number {
162	  let sum = 0;
163	  for (let i = 0; i < a.length; i++) sum += a[i] * b[i];
164	  return sum;
165	}
166	
167	function euclideanDistance(a: Float32Array, b: Float32Array): number {
168	  let sum = 0;
169	  for (let i = 0; i < a.length; i++) { const d = a[i] - b[i]; sum += d * d; }
170	  return Math.sqrt(sum);
171	}
172	
173	/** Validate a file path is safe (no null bytes, no traversal above root) */
