241	      autoPersistInterval: config.autoPersistInterval ?? DEFAULT_PERSIST_INTERVAL,
242	    };
243	    validatePath(this.config.databasePath);
244	  }
245	
246	  async initialize(): Promise<void> {
247	    if (this.initialized) return;
248	
249	    const useNative = await this.tryNativeInit();
250	    if (!useNative) {
251	      this.hnswIndex = new HnswLite(
