260	    if (this.config.autoPersistInterval > 0 && this.config.databasePath !== ':memory:') {
261	      this.persistTimer = setInterval(() => {
262	        if (this.dirty && !this.persisting) this.persistToDisk().catch(() => {});
263	      }, this.config.autoPersistInterval);
264	      if (this.persistTimer.unref) this.persistTimer.unref();
265	    }
266	
267	    this.initialized = true;
268	    if (this.config.verbose) {
269	      const mode = this.nativeDb ? 'native @ruvector/rvf' : 'pure-TS fallback';
270	      console.log(`[RvfBackend] Initialized (${mode}), ${this.entries.size} entries loaded`);
271	    }
272	  }
273	
274	  async shutdown(): Promise<void> {
275	    if (!this.initialized) return;
276	
277	    if (this.persistTimer) {
278	      clearInterval(this.persistTimer);
279	      this.persistTimer = null;
280	    }
281	
282	    if (this.dirty) {
283	      await this.persistToDisk();
284	    }
285	
286	    if (this.nativeDb) {
287	      try { await this.nativeDb.close(); } catch {}
288	      this.nativeDb = null;
289	    }
290	
291	    this.entries.clear();
292	    this.keyIndex.clear();
293	    this.hnswIndex = null;
294	    this.initialized = false;
295	  }
296	
297	  async store(entry: MemoryEntry): Promise<void> {
298	    const ns = entry.namespace || this.config.defaultNamespace;
299	    const e = ns !== entry.namespace ? { ...entry, namespace: ns } : entry;
300	    this.entries.set(e.id, e);
301	    this.keyIndex.set(this.compositeKey(e.namespace, e.key), e.id);
302	    if (e.embedding && this.hnswIndex) {
303	      this.hnswIndex.add(e.id, e.embedding);
304	    }
305	    this.dirty = true;
306	  }
307	
308	  async get(id: string): Promise<MemoryEntry | null> {
309	    const entry = this.entries.get(id);
310	    if (!entry) return null;
311	    entry.accessCount++;
312	    entry.lastAccessedAt = Date.now();
313	    return entry;
314	  }
315	
316	  async getByKey(namespace: string, key: string): Promise<MemoryEntry | null> {
317	    const id = this.keyIndex.get(this.compositeKey(namespace, key));
318	    if (!id) return null;
319	    return this.get(id);
320	  }
321	
322	  async update(id: string, updateData: MemoryEntryUpdate): Promise<MemoryEntry | null> {
323	    const entry = this.entries.get(id);
324	    if (!entry) return null;
325	
326	    const updated: MemoryEntry = {
327	      ...entry,
328	      ...updateData,
329	      updatedAt: Date.now(),
330	      version: entry.version + 1,
331	    };
332	    this.entries.set(id, updated);
333	    this.dirty = true;
334	    return updated;
335	  }
336	
337	  async delete(id: string): Promise<boolean> {
338	    const entry = this.entries.get(id);
339	    if (!entry) return false;
340	    this.entries.delete(id);
341	    this.keyIndex.delete(this.compositeKey(entry.namespace, entry.key));
342	    if (this.hnswIndex) this.hnswIndex.remove(id);
343	    this.dirty = true;
344	    return true;
345	  }
346	
347	  async query(q: MemoryQuery): Promise<MemoryEntry[]> {
348	    const start = performance.now();
349	    let results = Array.from(this.entries.values());
350	
351	    if (q.namespace) results = results.filter(e => e.namespace === q.namespace);
352	    if (q.key) results = results.filter(e => e.key === q.key);
353	    if (q.keyPrefix) results = results.filter(e => e.key.startsWith(q.keyPrefix!));
354	    if (q.tags?.length) results = results.filter(e => q.tags!.every(t => e.tags.includes(t)));
355	    if (q.memoryType) results = results.filter(e => e.type === q.memoryType);
356	    if (q.accessLevel) results = results.filter(e => e.accessLevel === q.accessLevel);
357	    if (q.ownerId) results = results.filter(e => e.ownerId === q.ownerId);
358	    if (q.createdAfter) results = results.filter(e => e.createdAt > q.createdAfter!);
359	    if (q.createdBefore) results = results.filter(e => e.createdAt < q.createdBefore!);
360	    if (q.updatedAfter) results = results.filter(e => e.updatedAt > q.updatedAfter!);
361	    if (q.updatedBefore) results = results.filter(e => e.updatedAt < q.updatedBefore!);
362	    if (!q.includeExpired) {
363	      const now = Date.now();
364	      results = results.filter(e => !e.expiresAt || e.expiresAt > now);
365	    }
366	
367	    if (q.type === 'semantic' && q.embedding && this.hnswIndex) {
368	      const searchResults = this.hnswIndex.search(q.embedding, q.limit, q.threshold);
369	      const idSet = new Set(searchResults.map(r => r.id));
370	      results = results.filter(e => idSet.has(e.id));
371	    }
372	
373	    const offset = q.offset ?? 0;
374	    results = results.slice(offset, offset + q.limit);
375	
376	    this.recordTiming(this.queryTimes, start);
377	    return results;
378	  }
379	
380	  async search(embedding: Float32Array, options: SearchOptions): Promise<SearchResult[]> {
381	    const start = performance.now();
382	    let results: SearchResult[];
383	
384	    if (this.hnswIndex) {
385	      const raw = this.hnswIndex.search(embedding, options.k * 2, options.threshold);
386	      results = [];
387	      for (const r of raw) {
388	        const entry = this.entries.get(r.id);
389	        if (!entry) continue;
390	        if (options.filters?.namespace && entry.namespace !== options.filters.namespace) continue;
391	        if (options.filters?.tags && !options.filters.tags.every(t => entry.tags.includes(t))) continue;
392	        if (options.filters?.memoryType && entry.type !== options.filters.memoryType) continue;
393	        results.push({ entry, score: r.score, distance: 1 - r.score });
394	      }
395	      results = results.slice(0, options.k);
396	    } else {
397	      results = this.bruteForceSearch(embedding, options);
398	    }
399	
400	    this.recordTiming(this.searchTimes, start);
401	    return results;
402	  }
403	
404	  async bulkInsert(entries: MemoryEntry[]): Promise<void> {
405	    for (const entry of entries) {
406	      this.entries.set(entry.id, entry);
407	      this.keyIndex.set(this.compositeKey(entry.namespace, entry.key), entry.id);
408	      if (entry.embedding && this.hnswIndex) this.hnswIndex.add(entry.id, entry.embedding);
409	    }
410	    this.dirty = true;
411	  }
412	
413	  async bulkDelete(ids: string[]): Promise<number> {
414	    let count = 0;
415	    for (const id of ids) {
416	      const entry = this.entries.get(id);
417	      if (entry) {
418	        this.entries.delete(id);
419	        this.keyIndex.delete(this.compositeKey(entry.namespace, entry.key));
420	        if (this.hnswIndex) this.hnswIndex.remove(id);
421	        count++;
422	      }
423	    }
424	    this.dirty = true;
425	    return count;
426	  }
427	
428	  async count(namespace?: string): Promise<number> {
429	    if (!namespace) return this.entries.size;
430	    let c = 0;
431	    for (const entry of this.entries.values()) {
432	      if (entry.namespace === namespace) c++;
433	    }
434	    return c;
435	  }
436	
437	  async listNamespaces(): Promise<string[]> {
438	    const ns = new Set<string>();
439	    for (const entry of this.entries.values()) ns.add(entry.namespace);
440	    return Array.from(ns);
441	  }
442	
443	  async clearNamespace(namespace: string): Promise<number> {
444	    const toDelete: string[] = [];
445	    for (const [id, entry] of this.entries) {
446	      if (entry.namespace === namespace) toDelete.push(id);
447	    }
448	    for (const id of toDelete) {
449	      const entry = this.entries.get(id)!;
450	      this.entries.delete(id);
451	      this.keyIndex.delete(this.compositeKey(entry.namespace, entry.key));
452	      if (this.hnswIndex) this.hnswIndex.remove(id);
453	    }
454	    if (toDelete.length > 0) this.dirty = true;
455	    return toDelete.length;
456	  }
457	
458	  async getStats(): Promise<BackendStats> {
459	    const entriesByNamespace: Record<string, number> = {};
460	    const entriesByType: Record<string, number> = {};
461	    let memoryUsage = 0;
462	
463	    for (const entry of this.entries.values()) {
464	      entriesByNamespace[entry.namespace] = (entriesByNamespace[entry.namespace] ?? 0) + 1;
465	      entriesByType[entry.type] = (entriesByType[entry.type] ?? 0) + 1;
466	      memoryUsage += entry.content.length * 2;
467	      if (entry.embedding) memoryUsage += entry.embedding.byteLength;
468	    }
469	
470	    const avgQuery = this.avg(this.queryTimes);
471	    const avgSearch = this.avg(this.searchTimes);
472	
473	    return {
474	      totalEntries: this.entries.size,
475	      entriesByNamespace,
476	      entriesByType: entriesByType as Record<MemoryType, number>,
477	      memoryUsage,
478	      hnswStats: this.hnswIndex ? {
479	        vectorCount: this.hnswIndex.size,
480	        memoryUsage: this.hnswIndex.size * this.config.dimensions * 4,
481	        avgSearchTime: avgSearch,
482	        buildTime: 0,
483	      } : undefined,
484	      avgQueryTime: avgQuery,
485	      avgSearchTime: avgSearch,
486	    };
487	  }
488	
489	  async healthCheck(): Promise<HealthCheckResult> {
490	    const issues: string[] = [];
491	    const recommendations: string[] = [];
492	
493	    if (!this.initialized) issues.push('Backend not initialized');
494	    if (!this.hnswIndex && !this.nativeDb) {
495	      issues.push('No vector index available');
496	      recommendations.push('Install @ruvector/rvf for native HNSW performance');
497	    }
498	
499	    const status = issues.length === 0
500	      ? 'healthy'
501	      : issues.some(i => i.includes('not initialized')) ? 'unhealthy' : 'degraded';
502	
503	    return {
504	      status,
505	      components: {
506	        storage: { status: this.initialized ? 'healthy' : 'unhealthy', latency: 0 },
507	        index: { status: this.hnswIndex || this.nativeDb ? 'healthy' : 'degraded', latency: 0 },
508	        cache: { status: 'healthy', latency: 0 },
509	      },
510	      timestamp: Date.now(),
511	      issues,
512	      recommendations,
513	    };
514	  }
515	
516	  private async tryNativeInit(): Promise<boolean> {
517	    try {
518	      const rvf = await import('@ruvector/rvf' as string);
519	      this.nativeDb = new rvf.RvfDatabase({
520	        path: this.config.databasePath,
521	        dimensions: this.config.dimensions,
522	        metric: this.config.metric,
523	        quantization: this.config.quantization,
524	        hnswM: this.config.hnswM,
525	        hnswEfConstruction: this.config.hnswEfConstruction,
526	        maxElements: this.config.maxElements,
527	      });
528	      await this.nativeDb.open();
529	      if (this.config.verbose) {
530	        console.log('[RvfBackend] Native @ruvector/rvf loaded successfully');
531	      }
532	      return true;
533	    } catch {
534	      if (this.config.verbose) {
535	        console.log('[RvfBackend] @ruvector/rvf not available, using pure-TS fallback');
536	      }
537	      return false;
538	    }
539	  }
540	
541	  private compositeKey(namespace: string, key: string): string {
542	    return `${namespace}\0${key}`;
543	  }
544	
545	  private bruteForceSearch(embedding: Float32Array, options: SearchOptions): SearchResult[] {
546	    const results: SearchResult[] = [];
547	    for (const entry of this.entries.values()) {
548	      if (!entry.embedding) continue;
549	      const score = cosineSimilarity(embedding, entry.embedding);
550	      if (options.threshold && score < options.threshold) continue;
551	      if (options.filters?.namespace && entry.namespace !== options.filters.namespace) continue;
552	      if (options.filters?.tags && !options.filters.tags.every(t => entry.tags.includes(t))) continue;
553	      results.push({ entry, score, distance: 1 - score });
554	    }
555	    results.sort((a, b) => b.score - a.score);
556	    return results.slice(0, options.k);
557	  }
558	
559	  private recordTiming(arr: number[], start: number): void {
560	    arr.push(performance.now() - start);
561	    if (arr.length > 100) arr.shift();
562	  }
563	
564	  private avg(arr: number[]): number {
565	    return arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
566	  }
567	
568	  private async loadFromDisk(): Promise<void> {
569	    if (this.config.databasePath === ':memory:') return;
570	    if (!existsSync(this.config.databasePath)) return;
571	
572	    try {
573	      const raw = await readFile(this.config.databasePath);
574	      if (raw.length < 8) return;
575	
576	      const magic = String.fromCharCode(raw[0], raw[1], raw[2], raw[3]);
577	      if (magic !== MAGIC) return;
578	
579	      const headerLen = raw.readUInt32LE(4);
580	      const MAX_HEADER_SIZE = 10 * 1024 * 1024; // 10MB max header
581	      if (headerLen > MAX_HEADER_SIZE || 8 + headerLen > raw.length) return;
582	      const headerJson = raw.subarray(8, 8 + headerLen).toString('utf-8');
583	      let header: RvfHeader;
584	      try {
585	        header = JSON.parse(headerJson);
586	      } catch {
587	        if (this.config.verbose) console.error('[RvfBackend] Corrupt RVF header');
588	        return;
589	      }
590	      if (!header || typeof header.entryCount !== 'number' || typeof header.version !== 'number') return;
591	
592	      let offset = 8 + headerLen;
593	      for (let i = 0; i < header.entryCount; i++) {
594	        if (offset + 4 > raw.length) break;
595	        const entryLen = raw.readUInt32LE(offset);
596	        offset += 4;
597	        if (offset + entryLen > raw.length) break;
598	
599	        const entryJson = raw.subarray(offset, offset + entryLen).toString('utf-8');
600	        offset += entryLen;
601	
602	        const parsed = JSON.parse(entryJson);
603	        if (parsed.embedding) parsed.embedding = new Float32Array(parsed.embedding);
604	
605	        const entry: MemoryEntry = parsed;
606	        this.entries.set(entry.id, entry);
607	        this.keyIndex.set(this.compositeKey(entry.namespace, entry.key), entry.id);
608	        if (entry.embedding && this.hnswIndex) this.hnswIndex.add(entry.id, entry.embedding);
609	      }
610	    } catch (err) {
611	      if (this.config.verbose) {
612	        console.error('[RvfBackend] Error loading from disk:', err);
613	      }
614	    }
615	  }
616	
617	  private persistQueue: Promise<void> = Promise.resolve();
618	
619	  private async persistToDisk(): Promise<void> {
620	    if (this.config.databasePath === ':memory:') return;
621	    // Queue writes so concurrent callers wait instead of silently dropping
622	    this.persistQueue = this.persistQueue.then(() => this.doPersist()).catch(() => {});
623	    return this.persistQueue;
624	  }
625	
626	  private async doPersist(): Promise<void> {
627	    if (!this.dirty) return;
628	    if (this.persisting) return;
629	    this.persisting = true;
630	
631	    try {
632	    const dir = dirname(this.config.databasePath);
633	    if (!existsSync(dir)) await mkdir(dir, { recursive: true });
634	
635	    const entries = Array.from(this.entries.values());
636	
637	    // Compute min createdAt without spread operator (avoids stack overflow for large arrays)
638	    let minCreatedAt = Date.now();
639	    for (const e of entries) {
640	      if (e.createdAt < minCreatedAt) minCreatedAt = e.createdAt;
641	    }
642	
643	    const header: RvfHeader = {
644	      magic: MAGIC,
645	      version: VERSION,
646	      dimensions: this.config.dimensions,
647	      metric: this.config.metric,
648	      quantization: this.config.quantization,
649	      entryCount: entries.length,
650	      createdAt: entries.length > 0 ? minCreatedAt : Date.now(),
651	      updatedAt: Date.now(),
652	    };
653	
654	    const headerBuf = Buffer.from(JSON.stringify(header), 'utf-8');
655	    const entryBuffers: Buffer[] = [];
656	
657	    for (const entry of entries) {
658	      const serialized = {
659	        ...entry,
660	        embedding: entry.embedding ? Array.from(entry.embedding) : undefined,
661	      };
662	      const buf = Buffer.from(JSON.stringify(serialized), 'utf-8');
663	      const lenBuf = Buffer.alloc(4);
664	      lenBuf.writeUInt32LE(buf.length, 0);
665	      entryBuffers.push(lenBuf, buf);
666	    }
667	
668	    const magicBuf = Buffer.from([0x52, 0x56, 0x46, 0x00]);
669	    const headerLenBuf = Buffer.alloc(4);
670	    headerLenBuf.writeUInt32LE(headerBuf.length, 0);
671	
672	    const output = Buffer.concat([magicBuf, headerLenBuf, headerBuf, ...entryBuffers]);
673	
674	    // Atomic write: write to temp file then rename (crash-safe)
675	    const tmpPath = this.config.databasePath + '.tmp';
676	    await writeFile(tmpPath, output);
677	    await rename(tmpPath, this.config.databasePath);
678	    this.dirty = false;
679	    } finally {
680	      this.persisting = false;
681	    }
682	  }
683	}
