for root in ['v3/@claude-flow/memory/src', 'v3/@claude-flow/embeddings/src', 'v3/@claude-flow/shared/src']:
    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            if fn.endswith('.ts') and not fn.endswith('.test.ts') and fn != 'index.ts':
                src_files.append(os.path.join(dirpath, fn))

# Collect all test file content
