1	/**
2	 * MemoryConsolidator — ADR-125 Phase 4
3	 *
4	 * Periodic maintenance for the in-memory state owned by {@link UnifiedMemoryService}.
5	 *
6	 * Operations:
7	 * - `sweepExpired()` — drop entries past `expiresAt` from all indexes (including HNSW).
8	 * - `dedup(strategy)` — collapse content-hash duplicates per strategy.
9	 * - `compactHnsw()` — rebuild the HNSW index from current `entries`.
10	 * - `runAll()` — sweep → dedup → compact in order.
11	 *
12	 * Invoked from two paths:
13	 * 1. {@link UnifiedMemoryService}'s lifecycle (background timer when
14	 *    `consolidator.autoRun === true`, plus `close()`).
15	 * 2. The AgentDB `nightlyLearner` controller (`src/controller-registry.ts`)
16	 *    delegates to `runAll()` instead of hitting AgentDB directly.
17	 *
18	 * Phase 3 placeholder lives in this file too — it provides the typed
19	 * surface that {@link UnifiedMemoryService.getConsolidator} resolves to.
20	 * The real implementation lands with Phase 4.
21	 *
22	 * @module v3/memory/consolidator
23	 */
24	
25	import { createHash } from 'node:crypto';
26	import { HNSWIndex } from './hnsw-index.js';
27	import type { MemoryEntry } from './types.js';
28	
29	/**
30	 * Strategy for resolving content-hash duplicates inside {@link MemoryConsolidator.dedup}.
31	 */
32	export type DedupStrategy = 'keep-newest' | 'keep-oldest' | 'merge-tags';
33	
34	export interface ConsolidatorOptions {
35	  /** Default strategy when `dedup()` is invoked with no argument. */
36	  dedupStrategy?: DedupStrategy;
37	  /** Used by `MemoryService` when scheduling automatic runs (ms). */
38	  intervalMs?: number;
39	}
40	
41	export interface SweepResult {
42	  removed: number;
43	  remaining: number;
44	  hnswRemoved: number;
45	}
46	
47	export interface DedupResult {
48	  merged: number;
49	  groups: number;
50	}
51	
52	export interface CompactResult {
53	  before: number;
54	  after: number;
55	  durationMs: number;
56	}
57	
58	export interface ConsolidationResult {
59	  sweep: SweepResult;
60	  dedup: DedupResult;
61	  compact: CompactResult;
62	  totalDurationMs: number;
63	}
64	
65	/**
66	 * Minimal surface the consolidator needs from `UnifiedMemoryService`. Avoids
67	 * a circular type import.
68	 */
69	interface ServiceLike {
70	  getAdapter(): {
71	    // Internals we mutate. Cast-safe at runtime.
72	    entries: Map<string, MemoryEntry>;
73	    namespaceIndex: Map<string, Set<string>>;
74	    keyIndex: Map<string, string>;
75	    tagIndex: Map<string, Set<string>>;
76	    // Public HNSW accessor exists on AgentDBAdapter; cast through.
77	    [key: string]: any;
78	  };
79	}
80	
81	export class MemoryConsolidator {
82	  constructor(
83	    private readonly service: ServiceLike,
84	    private readonly opts: ConsolidatorOptions = {}
85	  ) {}
86	
87	  /**
88	   * Drop all entries whose `expiresAt` is in the past.
89	   */
90	  async sweepExpired(): Promise<SweepResult> {
91	    const adapter = this.service.getAdapter() as any;
92	    const entries: Map<string, MemoryEntry> = adapter.entries;
93	    const namespaceIndex: Map<string, Set<string>> = adapter.namespaceIndex;
94	    const keyIndex: Map<string, string> = adapter.keyIndex;
95	    const tagIndex: Map<string, Set<string>> = adapter.tagIndex;
96	    const index: HNSWIndex = adapter.index;
97	
98	    const now = Date.now();
99	    const toRemove: MemoryEntry[] = [];
100	    for (const entry of entries.values()) {
101	      if (entry.expiresAt != null && entry.expiresAt < now) {
102	        toRemove.push(entry);
103	      }
104	    }
105	
106	    let hnswRemoved = 0;
107	    for (const entry of toRemove) {
108	      entries.delete(entry.id);
109	      namespaceIndex.get(entry.namespace)?.delete(entry.id);
110	      keyIndex.delete(`${entry.namespace}:${entry.key}`);
111	      for (const tag of entry.tags) tagIndex.get(tag)?.delete(entry.id);
112	      if (entry.embedding) {
113	        const removed = await index.removePoint(entry.id);
114	        if (removed) hnswRemoved += 1;
115	      }
116	    }
117	
118	    // Clean up empty namespace/tag sets to keep memory bounded
119	    for (const [ns, ids] of namespaceIndex) {
120	      if (ids.size === 0) namespaceIndex.delete(ns);
121	    }
122	    for (const [tag, ids] of tagIndex) {
123	      if (ids.size === 0) tagIndex.delete(tag);
124	    }
125	
126	    return {
127	      removed: toRemove.length,
128	      remaining: entries.size,
129	      hnswRemoved,
130	    };
131	  }
132	
133	  /**
134	   * Collapse content-hash duplicates across all namespaces per `strategy`.
135	   *
136	   * - `keep-newest`: keep the entry with the highest `updatedAt`, drop the rest.
137	   * - `keep-oldest`: keep the entry with the lowest `createdAt`, drop the rest.
138	   * - `merge-tags`: keep newest, but union the tag sets of the duplicates first.
139	   */
140	  async dedup(strategy?: DedupStrategy): Promise<DedupResult> {
141	    const adapter = this.service.getAdapter() as any;
142	    const entries: Map<string, MemoryEntry> = adapter.entries;
143	    const namespaceIndex: Map<string, Set<string>> = adapter.namespaceIndex;
144	    const keyIndex: Map<string, string> = adapter.keyIndex;
145	    const tagIndex: Map<string, Set<string>> = adapter.tagIndex;
146	    const index: HNSWIndex = adapter.index;
147	
148	    const effective = strategy ?? this.opts.dedupStrategy ?? 'keep-newest';
149	
150	    // Bucket by content hash
151	    const buckets = new Map<string, MemoryEntry[]>();
152	    for (const entry of entries.values()) {
153	      const hash = createHash('sha256').update(entry.content).digest('hex');
154	      const bucket = buckets.get(hash);
155	      if (bucket) bucket.push(entry);
156	      else buckets.set(hash, [entry]);
157	    }
158	
159	    let merged = 0;
160	    let dupGroups = 0;
161	    for (const bucket of buckets.values()) {
162	      if (bucket.length <= 1) continue;
163	      dupGroups += 1;
164	
165	      // Choose keeper
166	      let keeper: MemoryEntry;
167	      if (effective === 'keep-oldest') {
168	        keeper = bucket.reduce((acc, e) =>
169	          e.createdAt < acc.createdAt ? e : acc
170	        );
171	      } else {
172	        // keep-newest + merge-tags share this branch
173	        keeper = bucket.reduce((acc, e) =>
174	          e.updatedAt > acc.updatedAt ? e : acc
175	        );
176	      }
177	
178	      if (effective === 'merge-tags') {
179	        const tagSet = new Set<string>(keeper.tags);
180	        for (const e of bucket) for (const t of e.tags) tagSet.add(t);
181	        const oldTags = keeper.tags;
182	        keeper.tags = [...tagSet];
183	        // Update tagIndex membership for newly-added tags
184	        for (const t of keeper.tags) {
185	          if (!oldTags.includes(t)) {
186	            if (!tagIndex.has(t)) tagIndex.set(t, new Set());
187	            tagIndex.get(t)!.add(keeper.id);
188	          }
189	        }
190	      }
191	
192	      // Drop everyone except the keeper
193	      for (const e of bucket) {
194	        if (e.id === keeper.id) continue;
195	        entries.delete(e.id);
196	        namespaceIndex.get(e.namespace)?.delete(e.id);
197	        const compositeKey = `${e.namespace}:${e.key}`;
198	        if (keyIndex.get(compositeKey) === e.id) {
199	          keyIndex.delete(compositeKey);
200	        }
201	        for (const tag of e.tags) tagIndex.get(tag)?.delete(e.id);
202	        if (e.embedding) {
203	          await index.removePoint(e.id);
204	        }
205	        merged += 1;
206	      }
207	    }
208	
209	    return { merged, groups: dupGroups };
210	  }
211	
212	  /**
213	   * Rebuild the HNSW index from the current set of entries with embeddings.
