1	/**
2	 * DatabaseProvider - Platform-aware database selection
3	 *
4	 * Automatically selects best backend:
5	 * - Linux/macOS: better-sqlite3 (native, fast)
6	 * - Windows: sql.js (WASM, universal) when native fails
7	 * - Fallback: JSON file storage
8	 *
9	 * @module v3/memory/database-provider
10	 */
11	
12	import { platform } from 'node:os';
13	import { existsSync } from 'node:fs';
14	import {
15	  IMemoryBackend,
16	  MemoryEntry,
17	  MemoryEntryInput,
18	  MemoryQuery,
19	  SearchOptions,
20	  SearchResult,
21	  BackendStats,
22	  HealthCheckResult,
23	  MemoryEntryUpdate,
24	} from './types.js';
25	import { SQLiteBackend, SQLiteBackendConfig } from './sqlite-backend.js';
26	import { SqlJsBackend, SqlJsBackendConfig } from './sqljs-backend.js';
27	import type { EmbeddingGenerator } from './types.js';
28	
29	/**
30	 * Available database provider types.
31	 *
32	 * ADR-125 Phase 2 added `'hybrid'` and `'agentdb'` so the package can deliver
33	 * ADR-009's "HybridBackend by default" promise through `createDatabase`.
34	 */
35	export type DatabaseProvider =
36	  | 'better-sqlite3'
37	  | 'sql.js'
38	  | 'json'
39	  | 'rvf'
40	  | 'hybrid'
41	  | 'agentdb'
42	  | 'auto';
43	
44	/**
45	 * Database creation options
46	 */
47	export interface DatabaseOptions {
48	  /** Preferred provider (auto = platform-aware selection) */
49	  provider?: DatabaseProvider;
50	
51	  /** Enable verbose logging */
52	  verbose?: boolean;
53	
54	  /** Enable WAL mode (better-sqlite3 only) */
55	  walMode?: boolean;
56	
57	  /** Enable query optimization */
58	  optimize?: boolean;
59	
60	  /** Default namespace */
61	  defaultNamespace?: string;
62	
63	  /** Maximum entries before auto-cleanup */
64	  maxEntries?: number;
65	
66	  /** Auto-persist interval for sql.js (milliseconds) */
67	  autoPersistInterval?: number;
68	
69	  /** Path to sql.js WASM file */
70	  wasmPath?: string;
71	
72	  /**
73	   * Embedding generator. Required for `'hybrid'` and `'agentdb'` providers
74	   * (and recommended for semantic search on any provider).
75	   */
76	  embeddingGenerator?: EmbeddingGenerator;
77	
78	  /** Vector dimensions for `'hybrid'` and `'agentdb'` providers (default 1536) */
79	  dimensions?: number;
80	}
81	
82	/**
83	 * Platform detection result
84	 */
85	interface PlatformInfo {
86	  os: string;
87	  isWindows: boolean;
88	  isMacOS: boolean;
89	  isLinux: boolean;
90	  recommendedProvider: DatabaseProvider;
91	}
92	
93	/**
94	 * Detect platform and recommend provider
95	 */
96	function detectPlatform(): PlatformInfo {
97	  const os = platform();
98	  const isWindows = os === 'win32';
99	  const isMacOS = os === 'darwin';
100	  const isLinux = os === 'linux';
101	
102	  // Recommend better-sqlite3 for Unix-like systems, sql.js for Windows
103	  const recommendedProvider: DatabaseProvider = isWindows ? 'sql.js' : 'better-sqlite3';
104	
105	  return {
106	    os,
107	    isWindows,
108	    isMacOS,
109	    isLinux,
110	    recommendedProvider,
111	  };
112	}
113	
114	/**
115	 * Test if RVF backend is available (always true — pure-TS fallback)
116	 */
117	async function testRvf(): Promise<boolean> {
118	  return true;
119	}
120	
121	/**
122	 * Test if better-sqlite3 is available and working
123	 */
124	async function testBetterSqlite3(): Promise<boolean> {
125	  try {
126	    const Database = (await import('better-sqlite3')).default;
127	    const testDb = new Database(':memory:');
128	    testDb.close();
129	    return true;
130	  } catch (error) {
131	    return false;
132	  }
133	}
134	
135	/**
136	 * Test if sql.js is available and working
137	 */
138	async function testSqlJs(): Promise<boolean> {
139	  try {
140	    const initSqlJs = (await import('sql.js')).default;
141	    const SQL = await initSqlJs();
142	    const testDb = new SQL.Database();
143	    testDb.close();
144	    return true;
145	  } catch (error) {
146	    return false;
147	  }
148	}
149	
150	/**
151	 * Select best available provider
152	 */
153	async function selectProvider(
154	  preferred?: DatabaseProvider,
155	  verbose: boolean = false
156	): Promise<DatabaseProvider> {
157	  if (preferred && preferred !== 'auto') {
158	    if (verbose) {
159	      console.log(`[DatabaseProvider] Using explicitly specified provider: ${preferred}`);
160	    }
161	    return preferred;
162	  }
163	
164	  const platformInfo = detectPlatform();
165	
166	  if (verbose) {
167	    console.log(`[DatabaseProvider] Platform detected: ${platformInfo.os}`);
168	    console.log(`[DatabaseProvider] Recommended provider: ${platformInfo.recommendedProvider}`);
169	  }
170	
171	  // Try RVF first (always available via pure-TS fallback, native when @ruvector/rvf installed)
172	  if (await testRvf()) {
173	    if (verbose) {
174	      console.log('[DatabaseProvider] RVF backend available');
175	    }
176	    return 'rvf';
177	  }
178	
179	  // Try recommended provider
180	  if (platformInfo.recommendedProvider === 'better-sqlite3') {
181	    if (await testBetterSqlite3()) {
182	      if (verbose) {
183	        console.log('[DatabaseProvider] better-sqlite3 available and working');
184	      }
185	      return 'better-sqlite3';
186	    } else if (verbose) {
187	      console.log('[DatabaseProvider] better-sqlite3 not available, trying sql.js');
188	    }
189	  }
190	
191	  // Try sql.js as fallback
192	  if (await testSqlJs()) {
193	    if (verbose) {
194	      console.log('[DatabaseProvider] sql.js available and working');
195	    }
196	    return 'sql.js';
197	  } else if (verbose) {
198	    console.log('[DatabaseProvider] sql.js not available, using JSON fallback');
199	  }
200	
201	  // Final fallback to JSON
202	  return 'json';
203	}
204	
205	/**
206	 * Create a database instance with platform-aware provider selection
207	 *
208	 * @param path - Database file path (:memory: for in-memory)
209	 * @param options - Database configuration options
210	 * @returns Initialized database backend
211	 *
212	 * @example
213	 * ```typescript
214	 * // Auto-select best provider for platform
215	 * const db = await createDatabase('./data/memory.db');
216	 *
217	 * // Force specific provider
218	 * const db = await createDatabase('./data/memory.db', {
219	 *   provider: 'sql.js'
220	 * });
221	 *
222	 * // With custom options
223	 * const db = await createDatabase('./data/memory.db', {
224	 *   verbose: true,
225	 *   optimize: true,
226	 *   autoPersistInterval: 10000
227	 * });
228	 * ```
229	 */
230	export async function createDatabase(
231	  path: string,
232	  options: DatabaseOptions = {}
233	): Promise<IMemoryBackend> {
234	  const {
235	    provider = 'auto',
236	    verbose = false,
237	    walMode = true,
238	    optimize = true,
239	    defaultNamespace = 'default',
240	    maxEntries = 1000000,
241	    autoPersistInterval = 5000,
242	    wasmPath,
243	    embeddingGenerator,
244	    dimensions = 1536,
245	  } = options;
246	
247	  // Select provider
248	  const selectedProvider = await selectProvider(provider, verbose);
249	
250	  if (verbose) {
251	    console.log(`[DatabaseProvider] Creating database with provider: ${selectedProvider}`);
252	    console.log(`[DatabaseProvider] Database path: ${path}`);
253	  }
254	
255	  let backend: IMemoryBackend;
256	
257	  switch (selectedProvider) {
258	    case 'better-sqlite3': {
259	      const config: Partial<SQLiteBackendConfig> = {
260	        databasePath: path,
261	        walMode,
262	        optimize,
263	        defaultNamespace,
264	        maxEntries,
265	        verbose,
266	      };
267	
268	      backend = new SQLiteBackend(config);
269	      break;
270	    }
271	
272	    case 'sql.js': {
273	      const config: Partial<SqlJsBackendConfig> = {
274	        databasePath: path,
275	        optimize,
276	        defaultNamespace,
277	        maxEntries,
278	        verbose,
279	        autoPersistInterval,
280	        wasmPath,
281	      };
282	
283	      backend = new SqlJsBackend(config);
284	      break;
285	    }
286	
287	    case 'rvf': {
288	      const { RvfBackend } = await import('./rvf-backend.js');
289	      backend = new RvfBackend({
290	        databasePath: path.replace(/\.(db|json)$/, '.rvf'),
291	        dimensions,
292	        verbose,
293	        defaultNamespace,
294	        autoPersistInterval,
295	      });
296	      break;
297	    }
298	
299	    case 'hybrid': {
300	      // ADR-009: SQLite for structured queries + AgentDB for semantic search.
301	      const { HybridBackend } = await import('./hybrid-backend.js');
302	      backend = new HybridBackend({
303	        sqlite: {
304	          databasePath: path,
305	          walMode,
306	          optimize,
307	          defaultNamespace,
308	          maxEntries,
309	          verbose,
310	        },
311	        agentdb: {
312	          dbPath: path.replace(/\.(db|json|rvf)$/, '.agentdb'),
313	          namespace: defaultNamespace,
314	          vectorDimension: dimensions,
315	          embeddingGenerator,
316	          maxEntries,
317	        },
318	        defaultNamespace,
319	        embeddingGenerator,
320	      });
321	      break;
322	    }
323	
324	    case 'agentdb': {
325	      const { AgentDBBackend } = await import('./agentdb-backend.js');
326	      backend = new AgentDBBackend({
327	        dbPath: path,
328	        namespace: defaultNamespace,
329	        vectorDimension: dimensions,
330	        embeddingGenerator,
331	        maxEntries,
332	      });
333	      break;
334	    }
335	
336	    case 'json': {
337	      // Simple JSON file backend (minimal implementation)
338	      backend = new JsonBackend(path, verbose);
339	      break;
340	    }
341	
342	    default:
343	      throw new Error(`Unknown database provider: ${selectedProvider}`);
344	  }
345	
346	  // Initialize the backend
347	  await backend.initialize();
348	
349	  if (verbose) {
350	    console.log(`[DatabaseProvider] Database initialized successfully`);
351	  }
352	
353	  return backend;
354	}
