1	/**
2	 * Agent-Scoped Memory - Support for Claude Code's 3-scope agent memory directories
3	 *
4	 * Claude Code organizes agent memory into three scopes:
5	 * - **project**: Shared across all collaborators (checked into git)
6	 * - **local**: Machine-specific, not shared (gitignored)
7	 * - **user**: Global per-user, spans all projects
8	 *
9	 * Each scope stores agent-specific memory in a named subdirectory,
10	 * enabling isolated yet transferable knowledge between agents.
11	 *
12	 * @module @claude-flow/memory/agent-memory-scope
13	 */
14	
15	import * as path from 'node:path';
16	import { existsSync, readdirSync, statSync } from 'node:fs';
17	import type { IMemoryBackend, MemoryEntry } from './types.js';
18	import { AutoMemoryBridge } from './auto-memory-bridge.js';
19	import type {
20	  AutoMemoryBridgeConfig,
21	  MemoryInsight,
22	  InsightCategory,
23	} from './auto-memory-bridge.js';
24	
25	// ===== Types =====
26	
27	/** Claude Code's 3-scope agent memory system */
28	export type AgentMemoryScope = 'project' | 'local' | 'user';
29	
30	/** Configuration for agent-scoped memory bridge */
31	export interface AgentScopedConfig extends AutoMemoryBridgeConfig {
32	  /** Agent name (used in directory path) */
33	  agentName: string;
34	  /** Memory scope */
35	  scope: AgentMemoryScope;
36	}
37	
38	/** Options for knowledge transfer between agents */
39	export interface TransferOptions {
40	  /** Source namespace to transfer from */
41	  sourceNamespace: string;
42	  /** Minimum confidence to include (default: 0.8) */
43	  minConfidence?: number;
44	  /** Maximum entries to transfer (default: 20) */
45	  maxEntries?: number;
46	  /** Filter by categories */
47	  categories?: InsightCategory[];
48	}
49	
50	/** Result of a knowledge transfer */
51	export interface TransferResult {
52	  /** Number of entries transferred */
53	  transferred: number;
54	  /** Number of entries skipped (below threshold or duplicate) */
55	  skipped: number;
56	}
57	
58	// ===== Internal Helpers =====
59	
60	/**
61	 * Find the git root directory by walking up from a starting directory.
62	 * Synchronous variant for path resolution (no async needed for stat checks).
63	 */
64	function findGitRootSync(dir: string): string | null {
65	  let current = path.resolve(dir);
66	  const root = path.parse(current).root;
67	
68	  while (current !== root) {
69	    if (existsSync(path.join(current, '.git'))) {
70	      return current;
71	    }
72	    current = path.dirname(current);
73	  }
74	
75	  return null;
76	}
77	
78	/**
79	 * List agent subdirectories inside a given directory.
80	 * Returns an empty array if the directory does not exist or is unreadable.
81	 */
82	function listAgentsInDir(dir: string): string[] {
83	  if (!existsSync(dir)) return [];
84	  try {
85	    return readdirSync(dir).filter((name) => {
86	      try {
87	        return statSync(path.join(dir, name)).isDirectory();
88	      } catch {
89	        return false;
90	      }
91	    });
92	  } catch {
93	    return [];
94	  }
95	}
96	
97	// ===== Public Functions =====
98	
99	/**
100	 * Resolve the agent memory directory for a given agent name, scope, and working directory.
101	 *
102	 * Path resolution matches Claude Code binary behavior:
103	 * ```
104	 * project: <gitRoot>/.claude/agent-memory/<agentName>/
105	 * local:   <gitRoot>/.claude/agent-memory-local/<agentName>/
106	 * user:    ~/.claude/agent-memory/<agentName>/
107	 * ```
108	 *
109	 * Agent names are sanitized to prevent path traversal attacks.
110	 *
111	 * @param agentName - The agent identifier
112	 * @param scope - Memory scope: project, local, or user
113	 * @param workingDir - Working directory for git root detection (defaults to cwd)
114	 * @returns Absolute path to the agent's memory directory
115	 */
116	export function resolveAgentMemoryDir(
117	  agentName: string,
118	  scope: AgentMemoryScope,
119	  workingDir?: string,
120	): string {
121	  // Sanitize agent name to prevent path traversal
122	  const safeName = agentName.replace(/[^a-zA-Z0-9_-]/g, '_');
123	
124	  if (scope === 'user') {
125	    const home = process.env.HOME
126	      || process.env.USERPROFILE
127	      || (process.env.HOMEDRIVE && process.env.HOMEPATH ? process.env.HOMEDRIVE + process.env.HOMEPATH : '');
128	    if (!home) {
129	      throw new Error('Cannot determine home directory: HOME, USERPROFILE, and HOMEDRIVE+HOMEPATH are all undefined');
130	    }
131	    return path.join(home, '.claude', 'agent-memory', safeName);
132	  }
