1	/**
2	 * Knowledge Graph Module for @claude-flow/memory
3	 *
4	 * Builds a graph from MemoryEntry.references, computes PageRank,
5	 * detects communities via label propagation, and provides
6	 * graph-aware ranking for search results.
7	 *
8	 * Pure TypeScript - no external graph libraries.
9	 * @module v3/memory/memory-graph
10	 */
11	import { EventEmitter } from 'node:events';
12	import type { IMemoryBackend, MemoryEntry, SearchResult } from './types.js';
13	
14	// ===== Types =====
15	
16	export type EdgeType = 'reference' | 'similar' | 'temporal' | 'co-accessed' | 'causal';
17	
18	export interface MemoryGraphConfig {
19	  similarityThreshold?: number;   // Auto-edge threshold (default: 0.8)
20	  pageRankDamping?: number;       // Damping factor (default: 0.85)
21	  pageRankIterations?: number;    // Max iterations (default: 50)
22	  pageRankConvergence?: number;   // Convergence threshold (default: 1e-6)
23	  maxNodes?: number;              // Cap graph size (default: 5000)
24	  enableAutoEdges?: boolean;      // Auto-create edges from similarity (default: true)
25	  communityAlgorithm?: 'louvain' | 'label-propagation';  // default: label-propagation
26	}
27	
28	export interface GraphNode {
29	  id: string;
30	  category: string;
31	  confidence: number;
32	  accessCount: number;
33	  createdAt: number;
34	}
35	
36	export interface GraphEdge {
37	  targetId: string;
38	  type: EdgeType;
39	  weight: number;
40	}
41	
42	export interface RankedResult {
43	  entry: MemoryEntry;
44	  score: number;
45	  pageRank: number;
46	  combinedScore: number;
47	  community?: string;
48	}
49	
50	export interface GraphStats {
51	  nodeCount: number;
52	  edgeCount: number;
53	  avgDegree: number;
54	  communityCount: number;
55	  pageRankComputed: boolean;
56	  maxPageRank: number;
57	  minPageRank: number;
58	}
59	
60	const DEFAULT_CONFIG: Required<MemoryGraphConfig> = {
61	  similarityThreshold: 0.8,
62	  pageRankDamping: 0.85,
63	  pageRankIterations: 50,
64	  pageRankConvergence: 1e-6,
65	  maxNodes: 5000,
66	  enableAutoEdges: true,
67	  communityAlgorithm: 'label-propagation',
68	};
69	
70	/**
71	 * Knowledge graph built from memory entry references.
72	 * Supports PageRank, community detection (label propagation),
73	 * and graph-aware result ranking blending vector similarity with structural importance.
74	 */
75	export class MemoryGraph extends EventEmitter {
76	  private nodes: Map<string, GraphNode> = new Map();
77	  private edges: Map<string, GraphEdge[]> = new Map();
78	  private reverseEdges: Map<string, Set<string>> = new Map();
79	  private pageRanks: Map<string, number> = new Map();
80	  private communities: Map<string, string> = new Map();
81	  private config: Required<MemoryGraphConfig>;
82	  private dirty: boolean = true;
83	
84	  constructor(config?: MemoryGraphConfig) {
85	    super();
86	    this.config = { ...DEFAULT_CONFIG, ...config };
87	  }
88	
89	  /** Build graph from all entries in a backend. Creates nodes and reference edges. */
90	  async buildFromBackend(backend: IMemoryBackend, namespace?: string): Promise<void> {
91	    const entries = await backend.query({
92	      type: 'hybrid',
93	      namespace,
94	      limit: this.config.maxNodes,
95	    });
96	    for (const entry of entries) {
97	      this.addNode(entry);
98	    }
99	    for (const entry of entries) {
100	      for (const refId of entry.references) {
101	        this.addEdge(entry.id, refId, 'reference');
102	      }
103	    }
104	    this.dirty = true;
105	    this.emit('graph:built', { nodeCount: this.nodes.size });
106	  }
107	
108	  /** Add a node from a MemoryEntry. Skips silently at maxNodes capacity. */
109	  addNode(entry: MemoryEntry): void {
110	    if (this.nodes.size >= this.config.maxNodes && !this.nodes.has(entry.id)) {
111	      return;
112	    }
113	    this.nodes.set(entry.id, {
114	      id: entry.id,
115	      category: (entry.metadata?.category as string) || 'general',
116	      confidence: (entry.metadata?.confidence as number) || 0.5,
117	      accessCount: entry.accessCount,
118	      createdAt: entry.createdAt,
119	    });
120	    if (!this.edges.has(entry.id)) this.edges.set(entry.id, []);
121	    if (!this.reverseEdges.has(entry.id)) this.reverseEdges.set(entry.id, new Set());
122	    this.dirty = true;
123	  }
124	
125	  /** Add a directed edge. Skips if either node missing. Updates weight to max if exists. */
126	  addEdge(sourceId: string, targetId: string, type: EdgeType, weight: number = 1.0): void {
127	    if (!this.nodes.has(sourceId) || !this.nodes.has(targetId)) return;
128	
129	    const edgeList = this.edges.get(sourceId) || [];
130	    if (!this.edges.has(sourceId)) this.edges.set(sourceId, edgeList);
131	
132	    const existing = edgeList.find((e) => e.targetId === targetId);
133	    if (existing) {
134	      existing.weight = Math.max(existing.weight, weight);
135	    } else {
136	      edgeList.push({ targetId, type, weight });
137	    }
138	
139	    if (!this.reverseEdges.has(targetId)) this.reverseEdges.set(targetId, new Set());
140	    this.reverseEdges.get(targetId)!.add(sourceId);
141	    this.dirty = true;
142	  }
143	
144	  /** Remove a node and all associated edges (both directions). */
145	  removeNode(id: string): void {
146	    if (!this.nodes.has(id)) return;
147	
148	    // Remove outgoing edges and their reverse entries
149	    for (const edge of this.edges.get(id) || []) {
150	      this.reverseEdges.get(edge.targetId)?.delete(id);
151	    }
152	    this.edges.delete(id);
153	
154	    // Remove incoming edges pointing to this node
155	    const incoming = this.reverseEdges.get(id);
156	    if (incoming) {
157	      for (const sourceId of incoming) {
158	        const srcEdges = this.edges.get(sourceId);
159	        if (srcEdges) this.edges.set(sourceId, srcEdges.filter((e) => e.targetId !== id));
160	      }
161	    }
162	    this.reverseEdges.delete(id);
163	    this.nodes.delete(id);
164	    this.pageRanks.delete(id);
165	    this.communities.delete(id);
166	    this.dirty = true;
167	  }
168	
169	  /** Add similarity edges by searching backend. Returns count of edges added. */
170	  async addSimilarityEdges(backend: IMemoryBackend, entryId: string): Promise<number> {
171	    const entry = await backend.get(entryId);
172	    if (!entry || !entry.embedding) return 0;
173	
174	    const results = await backend.search(entry.embedding, {
175	      k: 20,
176	      threshold: this.config.similarityThreshold,
177	    });
178	
179	    let added = 0;
180	    for (const result of results) {
181	      if (result.entry.id === entryId) continue;
182	      if (result.score >= this.config.similarityThreshold) {
183	        const hadEdge = this.hasEdge(entryId, result.entry.id);
184	        this.addEdge(entryId, result.entry.id, 'similar', result.score);
185	        if (!hadEdge) added++;
186	      }
187	    }
188	    return added;
189	  }
190	
191	  /**
192	   * Compute PageRank via power iteration with dangling node redistribution.
193	   * Returns map of node ID to PageRank score.
194	   */
195	  computePageRank(): Map<string, number> {
196	    const N = this.nodes.size;
197	    if (N === 0) {
198	      this.dirty = false;
199	      this.emit('pagerank:computed', { iterations: 0 });
200	      return new Map();
201	    }
202	
203	    const d = this.config.pageRankDamping;
204	    for (const nodeId of this.nodes.keys()) {
205	      this.pageRanks.set(nodeId, 1 / N);
206	    }
207	
208	    // Identify dangling nodes (no outgoing edges)
209	    const danglingNodes: string[] = [];
210	    for (const nodeId of this.nodes.keys()) {
211	      const out = this.edges.get(nodeId);
212	      if (!out || out.length === 0) danglingNodes.push(nodeId);
213	    }
214	
215	    let iterations = 0;
216	    for (let iter = 0; iter < this.config.pageRankIterations; iter++) {
217	      let maxDelta = 0;
218	      const newRanks = new Map<string, number>();
219	
220	      let danglingSum = 0;
221	      for (const nodeId of danglingNodes) {
222	        danglingSum += this.pageRanks.get(nodeId) || 0;
223	      }
224	
225	      for (const nodeId of this.nodes.keys()) {
226	        let sum = 0;
227	        const incoming = this.reverseEdges.get(nodeId);
228	        if (incoming) {
229	          for (const sourceId of incoming) {
230	            const outDegree = this.edges.get(sourceId)?.length || 1;
231	            sum += (this.pageRanks.get(sourceId) || 0) / outDegree;
232	          }
233	        }
234	        const newRank = (1 - d) / N + d * (sum + danglingSum / N);
235	        newRanks.set(nodeId, newRank);
236	        maxDelta = Math.max(maxDelta, Math.abs(newRank - (this.pageRanks.get(nodeId) || 0)));
237	      }
238	
239	      this.pageRanks = newRanks;
240	      iterations = iter + 1;
241	      if (maxDelta < this.config.pageRankConvergence) break;
