1	/**
2	 * LearningBridge - Connects AutoMemoryBridge to NeuralLearningSystem
3	 *
4	 * When insights are recorded via AutoMemoryBridge, this module triggers
5	 * neural learning trajectories so the system continuously improves from
6	 * its own discoveries. The NeuralLearningSystem dependency is optional:
7	 * when unavailable, all operations degrade gracefully to no-ops.
8	 *
9	 * @module @claude-flow/memory/learning-bridge
10	 */
11	
12	import { EventEmitter } from 'node:events';
13	import type { IMemoryBackend, MemoryEntry, SONAMode } from './types.js';
14	import type { MemoryInsight, InsightCategory } from './auto-memory-bridge.js';
15	
16	// ===== Types =====
17	
18	/**
19	 * Factory function that returns a neural system instance.
20	 * Used for dependency injection so tests can supply a mock.
21	 */
22	export type NeuralLoader = () => Promise<any>;
23	
24	/** Configuration for the LearningBridge */
25	export interface LearningBridgeConfig {
26	  /** SONA operating mode (default: 'balanced') */
27	  sonaMode?: SONAMode;
28	  /** Per-hour confidence decay rate (default: 0.005) */
29	  confidenceDecayRate?: number;
30	  /** Confidence boost per access (default: 0.03) */
31	  accessBoostAmount?: number;
32	  /** Maximum confidence value (default: 1.0) */
33	  maxConfidence?: number;
34	  /** Minimum confidence floor (default: 0.1) */
35	  minConfidence?: number;
36	  /** EWC regularization strength (default: 2000) */
37	  ewcLambda?: number;
38	  /** Min active trajectories before consolidation runs (default: 10) */
39	  consolidationThreshold?: number;
40	  /** Enable the bridge (default: true). When false all methods are no-ops */
41	  enabled?: boolean;
42	  /**
43	   * Optional factory for the neural learning system.
44	   * When provided, this replaces the default dynamic import of @claude-flow/neural.
45	   * Primarily used for testing.
46	   */
47	  neuralLoader?: NeuralLoader;
48	}
49	
50	/** Aggregated learning statistics */
51	export interface LearningStats {
52	  totalTrajectories: number;
53	  completedTrajectories: number;
54	  activeTrajectories: number;
55	  totalConsolidations: number;
56	  totalDecays: number;
57	  avgConfidenceBoost: number;
58	  neuralAvailable: boolean;
59	}
60	
61	/** Result returned by consolidate() */
62	export interface ConsolidateResult {
63	  trajectoriesCompleted: number;
64	  patternsLearned: number;
65	  entriesUpdated: number;
66	  durationMs: number;
67	}
68	
69	/** A single pattern match returned by findSimilarPatterns() */
70	export interface PatternMatch {
71	  content: string;
72	  similarity: number;
73	  category: string;
74	  confidence: number;
75	}
76	
77	// ===== Defaults =====
78	
79	/** Internal resolved config type where neuralLoader stays optional */
80	type ResolvedConfig = Required<Omit<LearningBridgeConfig, 'neuralLoader'>> & {
81	  neuralLoader?: NeuralLoader;
82	};
83	
84	const DEFAULT_CONFIG: ResolvedConfig = {
85	  sonaMode: 'balanced',
86	  confidenceDecayRate: 0.005,
87	  accessBoostAmount: 0.03,
88	  maxConfidence: 1.0,
89	  minConfidence: 0.1,
90	  ewcLambda: 2000,
91	  consolidationThreshold: 10,
92	  enabled: true,
93	};
94	
95	const MS_PER_HOUR = 3_600_000;
96	
97	// ===== LearningBridge =====
98	
99	/**
100	 * Connects AutoMemoryBridge insights to the NeuralLearningSystem.
101	 *
102	 * @example
103	 * ```typescript
104	 * const bridge = new LearningBridge(memoryBackend);
105	 * await bridge.onInsightRecorded(insight, entryId);
106	 * await bridge.onInsightAccessed(entryId);
107	 * const result = await bridge.consolidate();
108	 * ```
109	 */
110	export class LearningBridge extends EventEmitter {
111	  private neural: any | null = null;
112	  private backend: IMemoryBackend;
113	  private config: ResolvedConfig;
114	  private activeTrajectories: Map<string, string> = new Map();
115	  private stats = {
116	    totalTrajectories: 0,
117	    completedTrajectories: 0,
118	    totalConsolidations: 0,
119	    totalDecays: 0,
120	    confidenceBoosts: 0,
121	    totalBoostAmount: 0,
122	  };
123	  private destroyed = false;
124	  private neuralInitPromise: Promise<void> | null = null;
125	
126	  constructor(backend: IMemoryBackend, config?: LearningBridgeConfig) {
127	    super();
128	    this.backend = backend;
129	    this.config = { ...DEFAULT_CONFIG, ...config };
130	  }
131	
132	  // ===== Public API =====
133	
134	  /**
135	   * Notify the bridge that an insight has been recorded in AgentDB.
136	   * Creates a learning trajectory so the neural system can track the
137	   * insight's lifecycle.
138	   */
139	  async onInsightRecorded(insight: MemoryInsight, entryId: string): Promise<void> {
140	    if (!this.config.enabled || this.destroyed) return;
141	
142	    await this.initNeural();
143	
144	    if (this.neural) {
145	      try {
146	        const trajectoryId = this.neural.beginTask(insight.summary, 'general');
147	        this.activeTrajectories.set(entryId, trajectoryId);
148	        this.stats.totalTrajectories++;
149	
150	        const embedding = this.createHashEmbedding(insight.summary);
151	        this.neural.recordStep(trajectoryId, {
152	          action: `record:${insight.category}`,
153	          reward: insight.confidence,
154	          stateEmbedding: embedding,
155	        });
156	      } catch {
