// tests/rvf-consolidator.test.ts
import { describe, it, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import { MemoryConsolidator } from '../v3/@claude-flow/memory/src/consolidator.js';

/**
 * Builds a minimal service-like mock with all indexes the consolidator needs.
 */
function makeService(initialEntries: Record<string, any> = {}) {
  const entries = new Map<string, any>();
  const namespaceIndex = new Map<string, Set<string>>();
  const keyIndex = new Map<string, string>();
  const tagIndex = new Map<string, Set<string>>();
  const index = {
    size: 0,
    removePoint: async () => true,
    // addPoint called during compactHnsw — track calls
    addPointCalls: [] as Array<{ id: string; vec: Float32Array }>,
    async addPoint(id: string, vec: Float32Array) {
      this.addPointCalls.push({ id, vec });
      this.size++;
    },
    getConfig() {
      return { dimensions: 4, M: 16, efConstruction: 200, maxElements: 10000, metric: 'cosine' };
    },
    on() {},
  };

  for (const [id, e] of Object.entries(initialEntries)) {
    entries.set(id, e);
    if (!namespaceIndex.has(e.namespace)) namespaceIndex.set(e.namespace, new Set());
    namespaceIndex.get(e.namespace)!.add(id);
    keyIndex.set(`${e.namespace}:${e.key}`, id);
    for (const tag of e.tags) {
      if (!tagIndex.has(tag)) tagIndex.set(tag, new Set());
      tagIndex.get(tag)!.add(id);
    }
    if (e.embedding) index.size++;
  }

  return {
    getAdapter: () => ({ entries, namespaceIndex, keyIndex, tagIndex, index }),
  };
}

function makeEntry(id: string, overrides: Record<string, any> = {}) {
  return {
    id,
    key: `key-${id}`,
    content: `content-${id}`,
    namespace: 'default',
    tags: ['tag1'],
    metadata: {},
    type: 'semantic',
    accessLevel: 'private',
    createdAt: Date.now() - 1000,
    updatedAt: Date.now(),
    version: 1,
    references: [],
    accessCount: 0,
    lastAccessedAt: Date.now(),
    expiresAt: undefined,
    embedding: undefined,
    ...overrides,
  };
}

describe('MemoryConsolidator', () => {
  describe('sweepExpired', () => {
    it('removes expired entries', async () => {
      const svc = makeService({
        e1: makeEntry('e1', { expiresAt: Date.now() - 100 }), // expired
        e2: makeEntry('e2', { expiresAt: Date.now() + 10000 }), // not expired
        e3: makeEntry('e3'), // no expiresAt
      });
      const c = new MemoryConsolidator(svc);
      const result = await c.sweepExpired();
      assert.equal(result.removed, 1);
      assert.equal(result.remaining, 2);
      assert.equal(svc.getAdapter().entries.has('e1'), false);
    });

    it('cleans up empty namespace sets', async () => {
      const svc = makeService({
        e1: makeEntry('e1', { namespace: 'temp', expiresAt: Date.now() - 1 }),
      });
      const c = new MemoryConsolidator(svc);
      await c.sweepExpired();
      assert.equal(svc.getAdapter().namespaceIndex.has('temp'), false);
    });

    it('handles empty entries gracefully', async () => {
      const svc = makeService();
      const c = new MemoryConsolidator(svc);
      const result = await c.sweepExpired();
      assert.equal(result.removed, 0);
      assert.equal(result.remaining, 0);
    });

    it('does not remove entries without expiresAt', async () => {
      const svc = makeService({ e1: makeEntry('e1') });
      const c = new MemoryConsolidator(svc);
      const result = await c.sweepExpired();
      assert.equal(result.removed, 0);
      assert.equal(result.remaining, 1);
    });
  });

  describe('dedup', () => {
    it('deduplicates identical content with keep-newest (default)', async () => {
      const svc = makeService({
        a: makeEntry('a', { content: 'duplicate', createdAt: 100, updatedAt: 200 }),
        b: makeEntry('b', { content: 'duplicate', createdAt: 150, updatedAt: 250 }), // newer
      });
      const c = new MemoryConsolidator(svc);
      const result = await c.dedup('keep-newest');
      assert.equal(result.merged, 1);
      assert.equal(svc.getAdapter().entries.has('a'), false); // older dropped
      assert.equal(svc.getAdapter().entries.has('b'), true); // newer kept
    });

    it('deduplicates with keep-oldest', async () => {
      const svc = makeService({
        a: makeEntry('a', { content: 'dup', createdAt: 100, updatedAt: 200 }), // older
        b: makeEntry('b', { content: 'dup', createdAt: 200, updatedAt: 300 }),
      });
      const c = new MemoryConsolidator(svc);
      const result = await c.dedup('keep-oldest');
      assert.equal(result.merged, 1);
      assert.equal(svc.getAdapter().entries.has('a'), true); // older kept
      assert.equal(svc.getAdapter().entries.has('b'), false);
    });

    it('deduplicates with merge-tags', async () => {
      const svc = makeService({
        a: makeEntry('a', { content: 'dup', tags: ['red', 'blue'] }),
        b: makeEntry('b', { content: 'dup', tags: ['blue', 'green'] }),
      });
      const c = new MemoryConsolidator(svc);
      const result = await c.dedup('merge-tags');
      assert.equal(result.merged, 1);
      const keeper = svc.getAdapter().entries.get('a');
      assert.ok(keeper.tags.includes('red'));
      assert.ok(keeper.tags.includes('blue'));
      assert.ok(keeper.tags.includes('green'));
    });

    it('skips unique content (no duplicates)', async () => {
      const svc = makeService({
        a: makeEntry('a', { content: 'alpha' }),
        b: makeEntry('b', { content: 'beta' }),
      });
      const c = new MemoryConsolidator(svc);
      const result = await c.dedup();
      assert.equal(result.merged, 0);
      assert.equal(svc.getAdapter().entries.size, 2);
    });
  });

  describe('compactHnsw', () => {
    it('rebuilds index from entries with embeddings', async () => {
      const svc = makeService({
        a: makeEntry('a', { embedding: new Float32Array([1, 0, 0, 0]) }),
        b: makeEntry('b', { embedding: new Float32Array([0, 1, 0, 0]) }),
        c: makeEntry('c'), // no embedding
      });
      const c = new MemoryConsolidator(svc);
      const result = await c.compactHnsw();
      assert.equal(result.after, 2); // only a and b have embeddings
      assert.ok(result.durationMs >= 0);
    });

    it('handles empty index', async () => {
      const svc = makeService({});
      const consolidator = new MemoryConsolidator(svc);
      const result = await consolidator.compactHnsw();
      assert.equal(result.after, 0);
    });
  });

  describe('runAll', () => {
    it('runs sweep → dedup → compact in order', async () => {
      const svc = makeService({
        a: makeEntry('a', { content: 'dup', expiresAt: Date.now() - 1, embedding: new Float32Array([1, 0, 0, 0]) }),
        b: makeEntry('b', { content: 'dup' }),
      });
      const c = new MemoryConsolidator(svc);
      const result = await c.runAll();
      assert.equal(result.sweep.removed, 1); // a expired
      assert.equal(result.dedup.merged, 0); // only b left — no duplicates
      assert.ok(result.totalDurationMs >= 0);
    });
  });
});
