    const e = this.entries.get(id);
    if (!e) return null;
    const updated = { ...e, ...u, version: e.version + 1, updatedAt: Date.now() };
    this.entries.set(id, updated);
    return updated;
  }
  async delete(id: string) { return this.entries.delete(id); }
  async query(q: any) {
    let results = [...this.entries.values()];
    if (q.namespace) results = results.filter(e => e.namespace === q.namespace);
    return results.slice(0, q.limit);
  }
  async search(emb: Float32Array, opts: any) { return []; }
  async bulkInsert(entries: MemoryEntry[]) { for (const e of entries) this.entries.set(e.id, e); }
  async bulkDelete(ids: string[]) { let c = 0; for (const id of ids) if (this.entries.delete(id)) c++; return c; }
  async count(ns?: string) {
    if (!ns) return this.entries.size;
    let c = 0; for (const e of this.entries.values()) if (e.namespace === ns) c++;
    return c;
  }
  async listNamespaces() { return [...new Set([...this.entries.values()].map(e => e.namespace))]; }
  async clearNamespace(ns: string) {
    let c = 0;
    for (const [id, e] of this.entries) if (e.namespace === ns) { this.entries.delete(id); c++; }
    return c;
  }
  async getStats() { return { totalEntries: this.entries.size, entriesByNamespace: {}, entriesByType: {} as any, memoryUsage: 0, avgQueryTime: 0, avgSearchTime: 0 }; }
