    assert.equal(ranks.size, 3);
    const sum = [...ranks.values()].reduce((a, b) => a + b, 0);
    assert.ok(Math.abs(sum - 1.0) < 0.01, `Expected sum ≈ 1.0, got ${sum}`);
  });

  it('computePageRank on empty graph returns empty map', () => {
    const ranks = graph.computePageRank();
    assert.equal(ranks.size, 0);
  });

  it('computePageRank converges on single node', () => {
    graph.addNode(makeEntry('solo'));
    const ranks = graph.computePageRank();
    assert.equal(ranks.get('solo'), 1.0);
  });

  // --- Community Detection ---
  it('detectCommunities assigns labels', () => {
    graph.addNode(makeEntry('a'));
    graph.addNode(makeEntry('b'));
    graph.addEdge('a', 'b', 'reference');
    const communities = graph.detectCommunities();
    assert.equal(communities.size, 2);
  });

  // --- Graph Ranking ---
  it('rankWithGraph blends vector score and PageRank', () => {
    graph.addNode(makeEntry('a'));
    graph.addNode(makeEntry('b'));
    graph.addEdge('a', 'b', 'reference');
    graph.computePageRank();

    const ranked = graph.rankWithGraph([
      { entry: makeEntry('b'), score: 0.9, distance: 0.1 },
      { entry: makeEntry('a'), score: 0.8, distance: 0.2 },
    ], 0.7);
    assert.equal(ranked.length, 2);
    // Results sorted descending by combinedScore
    for (let i = 1; i < ranked.length; i++) {
      assert.ok(ranked[i - 1].combinedScore >= ranked[i].combinedScore);
    }
  });

  // --- BFS Neighbors ---
  it('getNeighbors returns nodes at given depth', () => {
    graph.addNode(makeEntry('a'));
    graph.addNode(makeEntry('b'));
    graph.addNode(makeEntry('c'));
    graph.addEdge('a', 'b', 'reference');
    graph.addEdge('b', 'c', 'reference');
    const neighbors = graph.getNeighbors('a', 2);
    assert.ok(neighbors.has('b'));
    assert.ok(neighbors.has('c'));
  });

  it('getNeighbors returns empty set for isolated node', () => {
    graph.addNode(makeEntry('iso'));
    assert.equal(graph.getNeighbors('iso').size, 0);
  });

  it('getStats returns correct edge count', () => {
    graph.addNode(makeEntry('a'));
    graph.addNode(makeEntry('b'));
    graph.addEdge('a', 'b', 'reference');
    graph.addEdge('a', 'b', 'similar'); // count increases
    assert.equal(graph.getStats().edgeCount, 2);
  });

  // --- Empty Graph ---
  it('empty graph returns zero stats', () => {
    const stats = graph.getStats();
    assert.equal(stats.nodeCount, 0);
    assert.equal(stats.edgeCount, 0);
    assert.equal(stats.avgDegree, 0);
    assert.equal(stats.communityCount, 0);
  });
});
