    const origHome = process.env.HOME;
    delete process.env.HOME;
    try {
      assert.throws(() => resolveAgentMemoryDir('a', 'user'), /Cannot determine home directory/);
    } finally {
      process.env.HOME = origHome;
    }
  });

  it('resolves project scope with git root', () => {
    const tmp = mkdtempSync(join(tmpdir(), 'rvf-git-test-'));
    mkdirSync(join(tmp, '.git'));
    const dir = resolveAgentMemoryDir('tester', 'project', tmp);
    assert.ok(dir.startsWith(tmp));
    assert.ok(dir.includes('.claude/agent-memory/tester'));
    rmSync(tmp, { recursive: true, force: true });
  });

  it('resolves local scope separately from project', () => {
    const tmp = mkdtempSync(join(tmpdir(), 'rvf-local-test-'));
    mkdirSync(join(tmp, '.git'));
    const project = resolveAgentMemoryDir('agent', 'project', tmp);
    const local = resolveAgentMemoryDir('agent', 'local', tmp);
    assert.ok(project.includes('agent-memory/agent'));
    assert.ok(local.includes('agent-memory-local/agent'));
    assert.notEqual(project, local);
    rmSync(tmp, { recursive: true, force: true });
  });
});

